import{describe,it,expect,beforeEach}from"vitest";import{EventRecommendationEngine}from"../../frontend/js-modules/event-recommendation-engine.js";const sampleEvents=[{id:"diwali",name:"Diwali",category:"Religious",tags:["lights","family"],destinationId:"delhi",state:"Delhi",startMonth:10,endMonth:11,popularity:10},{id:"sunburn",name:"Sunburn Festival",category:"Music",tags:["edm","nightlife"],destinationId:"goa",state:"Goa",startMonth:12,endMonth:12,popularity:8},{id:"pongal",name:"Pongal",category:"Food",tags:["harvest","sweets"],destinationId:"madurai",state:"Tamil Nadu",startMonth:1,endMonth:1,popularity:8},{id:"margazhi",name:"Margazhi Season",category:"Music",tags:["carnatic","classical"],destinationId:"chennai",state:"Tamil Nadu",startMonth:12,endMonth:1,popularity:7}];describe("EventRecommendationEngine.filterByDestination",()=>{let e;beforeEach(()=>{e=new EventRecommendationEngine({events:sampleEvents})}),it("filters by destinationId",()=>{const t=e.filterByDestination(sampleEvents,{destinationId:"goa"});expect(t.map(e=>e.id)).toEqual(["sunburn"])}),it("filters by state when no destinationId matches",()=>{const t=e.filterByDestination(sampleEvents,{state:"Tamil Nadu"});expect(t.map(e=>e.id).sort()).toEqual(["margazhi","pongal"])}),it("returns all events when no criteria given",()=>{expect(e.filterByDestination(sampleEvents,{})).toEqual(sampleEvents)})}),describe("EventRecommendationEngine.filterByDateRange",()=>{let e;beforeEach(()=>{e=new EventRecommendationEngine({events:sampleEvents})}),it("matches events overlapping a single travel date",()=>{const t=e.filterByDateRange(sampleEvents,"2026-10-15");expect(t.map(e=>e.id)).toEqual(["diwali"])}),it("matches events overlapping a date range",()=>{const t=e.filterByDateRange(sampleEvents,"2026-12-01","2026-12-20");expect(t.map(e=>e.id).sort()).toEqual(["margazhi","sunburn"])}),it("handles year-wrapping event ranges (Dec-Jan)",()=>{const t=e.filterByDateRange(sampleEvents,"2027-01-05");expect(t.map(e=>e.id).sort()).toEqual(["margazhi","pongal"])}),it("returns all events when no start date is given",()=>{expect(e.filterByDateRange(sampleEvents,null)).toEqual(sampleEvents)})}),describe("EventRecommendationEngine.filterByCategories",()=>{let e;beforeEach(()=>{e=new EventRecommendationEngine({events:sampleEvents})}),it("filters by category name (case-insensitive)",()=>{const t=e.filterByCategories(sampleEvents,["music"]);expect(t.map(e=>e.id).sort()).toEqual(["margazhi","sunburn"])}),it("filters by tag as well as category",()=>{const t=e.filterByCategories(sampleEvents,["harvest"]);expect(t.map(e=>e.id)).toEqual(["pongal"])}),it("returns all events when no categories are given",()=>{expect(e.filterByCategories(sampleEvents,[])).toEqual(sampleEvents)})}),describe("EventRecommendationEngine.scoreEvent",()=>{let e;beforeEach(()=>{e=new EventRecommendationEngine}),it("scores purely on popularity when no interests given",()=>{const{score:t}=e.scoreEvent(sampleEvents[0],[]);expect(t).toBeCloseTo(1,5)}),it("boosts score when interests match category/tags",()=>{const{score:t,matchedInterests:n}=e.scoreEvent(sampleEvents[0],["religious","lights"]);expect(n.sort()).toEqual(["lights","religious"]),expect(t).toBeGreaterThan(0)}),it("scores lower when interests do not match at all",()=>{const t=e.scoreEvent(sampleEvents[0],["adventure"]).score,n=e.scoreEvent(sampleEvents[0],[]).score;expect(t).toBeLessThan(n)})}),describe("EventRecommendationEngine#recommend",()=>{let e;beforeEach(()=>{e=new EventRecommendationEngine({events:sampleEvents})}),it("ranks by match score, best first",()=>{const t=e.recommend({interests:["music"]});expect(t[0].matchScore).toBeGreaterThanOrEqual(t[t.length-1].matchScore)}),it("combines destination, date, and category filters",()=>{const t=e.recommend({state:"Tamil Nadu",startDate:"2026-01-10"});expect(t.map(e=>e.event.id).sort()).toEqual(["margazhi","pongal"])}),it("respects the limit option",()=>{const t=e.recommend({limit:1});expect(t.length).toBe(1)}),it("flags bookmarked events in the output",()=>{e.toggleBookmark("diwali");const t=e.recommend({}).find(e=>"diwali"===e.event.id);expect(t.isBookmarked).toBe(!0)})}),describe("EventRecommendationEngine bookmarks",()=>{let e;beforeEach(()=>{e=new EventRecommendationEngine({events:sampleEvents})}),it("toggles bookmarks on and off",()=>{expect(e.toggleBookmark("diwali")).toBe(!0),expect(e.isBookmarked("diwali")).toBe(!0),expect(e.toggleBookmark("diwali")).toBe(!1),expect(e.isBookmarked("diwali")).toBe(!1)}),it("lists bookmarked events",()=>{e.toggleBookmark("pongal"),e.toggleBookmark("sunburn"),expect(e.getBookmarkedEvents().map(e=>e.id).sort()).toEqual(["pongal","sunburn"])}),it("ignores an empty eventId",()=>{expect(e.toggleBookmark(null)).toBe(!1),expect(e.getBookmarkIds()).toEqual([])})}),describe("EventRecommendationEngine itinerary integration",()=>{it("builds an itinerary entry from an event",()=>{const e=EventRecommendationEngine.buildItineraryEntry(sampleEvents[0],{date:"2026-10-20"});expect(e.eventId).toBe("diwali"),expect(e.title).toBe("Diwali"),expect(e.date).toBe("2026-10-20"),expect(e.type).toBe("event")}),it("returns null for a missing event",()=>{expect(EventRecommendationEngine.buildItineraryEntry(null)).toBeNull()}),it("appends an event to an itinerary without mutating the original",()=>{const e=[{id:"day1",activity:"Arrive"}],t=EventRecommendationEngine.addEventToItinerary(e,sampleEvents[0]);expect(e.length).toBe(1),expect(t.length).toBe(2),expect(t[1].eventId).toBe("diwali")}),it("removes an event entry by id",()=>{const e=EventRecommendationEngine.addEventToItinerary([],sampleEvents[0]),t=e[0].id,n=EventRecommendationEngine.removeEventFromItinerary(e,t);expect(n.length).toBe(0)})}),describe("EventRecommendationEngine.getUpcomingReminders",()=>{it("flags events starting in the current month",()=>{const e=new Date("2026-10-05T00:00:00"),t=EventRecommendationEngine.getUpcomingReminders([sampleEvents[0]],e,1);expect(t.length).toBe(1),expect(t[0].monthsUntil).toBe(0)}),it("flags events starting within the lookahead window",()=>{const e=new Date("2026-11-01T00:00:00"),t=EventRecommendationEngine.getUpcomingReminders([sampleEvents[1]],e,1);expect(t.length).toBe(1),expect(t[0].monthsUntil).toBe(1)}),it("excludes events outside the lookahead window",()=>{const e=new Date("2026-06-01T00:00:00"),t=EventRecommendationEngine.getUpcomingReminders([sampleEvents[0]],e,1);expect(t.length).toBe(0)}),it("handles year-wrapping events near December/January",()=>{const e=new Date("2026-12-15T00:00:00"),t=EventRecommendationEngine.getUpcomingReminders([sampleEvents[3]],e,1);expect(t.length).toBe(1)})});